// Copies the SDK sources into the frontend so Launchpad's exports and downloads
// ship exactly this code. Run after editing the SDK:  node sdk/sync.mjs
// (tests/sdk.test.ts fails if the copy is out of date.)
import { readFileSync, writeFileSync } from "node:fs";

const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8").replace(/\r\n/g, "\n");
const version = JSON.parse(read("./js/package.json")).version;

export function render() {
  return [
    "// GENERATED by sdk/sync.mjs from sdk/js and sdk/python — do not edit by hand.",
    `export const SDK_VERSION = ${JSON.stringify(version)};`,
    `export const SDK_JS = ${JSON.stringify(read("./js/natlas.js"))};`,
    `export const SDK_DTS = ${JSON.stringify(read("./js/natlas.d.ts"))};`,
    `export const SDK_PY = ${JSON.stringify(read("./python/natlas.py"))};`,
    "",
  ].join("\n");
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, "/").split("/").pop())) {
  writeFileSync(new URL("../frontend/src/export/sdkSource.ts", import.meta.url), render());
  console.log("Wrote frontend/src/export/sdkSource.ts (natlas " + version + ")");
}
